// Core renderer: loads report.md, renders it and shows the repo's last push date.
// Students: do not edit this file — only report.md and images/.
(function () {
  "use strict";

  const $ = (id) => document.getElementById(id);

  // ---------- front matter ----------
  function parseFrontMatter(text) {
    const match = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?/);
    if (!match) return { meta: {}, body: text };
    const meta = {};
    for (const line of match[1].split(/\r?\n/)) {
      const kv = line.match(/^\s*([A-Za-z_][\w-]*)\s*:\s*(.*?)\s*$/);
      if (kv) meta[kv[1].toLowerCase()] = kv[2].replace(/^["']|["']$/g, "");
    }
    return { meta, body: text.slice(match[0].length) };
  }

  // ---------- math (KaTeX) as marked extensions ----------
  function renderMath(tex, displayMode) {
    try {
      return katex.renderToString(tex, { displayMode, throwOnError: false });
    } catch (e) {
      return `<code class="error">${tex}</code>`;
    }
  }

  const mathExtensions = [
    {
      name: "blockMath",
      level: "block",
      start(src) {
        const i = src.indexOf("$$");
        return i < 0 ? undefined : i;
      },
      tokenizer(src) {
        const m = src.match(/^\$\$([\s\S]+?)\$\$[^\S\n]*(?:\n|$)/);
        if (m) return { type: "blockMath", raw: m[0], text: m[1].trim() };
      },
      renderer(token) {
        return renderMath(token.text, true);
      },
    },
    {
      name: "inlineMath",
      level: "inline",
      start(src) {
        const i = src.indexOf("$");
        return i < 0 ? undefined : i;
      },
      tokenizer(src) {
        const display = src.match(/^\$\$([\s\S]+?)\$\$/);
        if (display) return { type: "inlineMath", raw: display[0], text: display[1].trim(), display: true };
        const m = src.match(/^\$(?!\s)((?:\\.|[^\\$\n])+?)(?<!\s)\$(?!\d)/);
        if (m) return { type: "inlineMath", raw: m[0], text: m[1], display: false };
      },
      renderer(token) {
        return renderMath(token.text, token.display);
      },
    },
  ];

  // ---------- table of contents ----------
  function slugify(text, used) {
    let base = text.toLowerCase().trim()
      .replace(/[^\p{L}\p{N}\s-]/gu, "")
      .replace(/\s+/g, "-") || "section";
    let slug = base, n = 2;
    while (used.has(slug)) slug = `${base}-${n++}`;
    used.add(slug);
    return slug;
  }

  function buildToc(article) {
    const headings = article.querySelectorAll("h2, h3");
    const used = new Set();
    const list = $("toc-list");
    list.innerHTML = "";
    headings.forEach((h) => {
      h.id = slugify(h.textContent, used);
      const li = document.createElement("li");
      li.className = `lvl-${h.tagName[1]}`;
      const a = document.createElement("a");
      a.href = `#${h.id}`;
      a.textContent = h.textContent;
      li.appendChild(a);
      list.appendChild(li);
    });
    if (headings.length < 2) return;
    $("toc").hidden = false;

    const links = new Map([...list.querySelectorAll("a")].map((a) => [a.hash.slice(1), a]));
    const observer = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        links.forEach((a) => a.classList.remove("active"));
        links.get(entry.target.id)?.classList.add("active");
      });
    }, { rootMargin: "-90px 0px -70% 0px" });
    headings.forEach((h) => observer.observe(h));
  }

  // ---------- metadata ----------
  function applyMeta(meta) {
    if (meta.title) {
      $("meta-title").textContent = meta.title;
      document.title = meta.title;
    }
    if (meta.course) $("meta-course").textContent = meta.course;
    if (meta.author) {
      $("meta-author").textContent = meta.author;
      $("meta-author-wrap").hidden = false;
    }
    if (meta.date) {
      $("meta-date").textContent = meta.date;
      $("meta-date-wrap").hidden = false;
    }
  }

  // ---------- last push date ----------
  // Detects owner/repo from the GitHub Pages URL: https://<owner>.github.io/<repo>/
  function detectRepo() {
    const host = location.hostname.toLowerCase();
    if (!host.endsWith(".github.io")) return null;
    const owner = host.slice(0, -".github.io".length);
    const first = location.pathname.split("/").filter(Boolean)[0];
    return { owner, repo: first || host };
  }

  function formatDate(iso) {
    return new Date(iso).toLocaleString("en-GB", {
      timeZone: "Europe/Kyiv",
      day: "numeric", month: "short", year: "numeric",
      hour: "2-digit", minute: "2-digit",
    }) + " (Kyiv)";
  }

  async function loadLastPush() {
    const out = $("last-push");
    const repo = detectRepo();
    if (!repo) {
      out.textContent = "n/a (local preview)";
      return;
    }
    const repoUrl = `https://github.com/${repo.owner}/${repo.repo}`;
    const link = $("repo-link");
    link.href = repoUrl;
    link.hidden = false;
    try {
      const res = await fetch(`https://api.github.com/repos/${repo.owner}/${repo.repo}`, {
        headers: { Accept: "application/vnd.github+json" },
      });
      if (!res.ok) throw new Error(res.status);
      const data = await res.json();
      out.innerHTML = "";
      const a = document.createElement("a");
      a.href = `${repoUrl}/commits/${data.default_branch}`;
      a.target = "_blank";
      a.rel = "noopener";
      a.textContent = formatDate(data.pushed_at);
      a.title = data.pushed_at;
      out.appendChild(a);
    } catch (e) {
      out.textContent = "unavailable";
    }
  }

  // ---------- main ----------
  async function loadReport() {
    const article = $("report-body");
    try {
      const res = await fetch("report.md", { cache: "no-cache" });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const { meta, body } = parseFrontMatter(await res.text());
      applyMeta(meta);
      marked.use({ gfm: true, extensions: mathExtensions });
      article.innerHTML = marked.parse(body);
      article.querySelectorAll("pre code").forEach((el) => hljs.highlightElement(el));
      article.querySelectorAll("a[href^='http']").forEach((a) => {
        a.target = "_blank";
        a.rel = "noopener";
      });
      buildToc(article);
      if (location.hash) document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView();
    } catch (e) {
      article.innerHTML =
        `<p class="error">Could not load report.md (${e.message}).</p>` +
        `<p class="muted">Opening index.html directly from disk does not work — run a local server, see README.</p>`;
    }
  }

  loadReport();
  loadLastPush();
})();
